render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(x = cfg$x, y = cfg$y), c("x", "y")); p <- ggplot2::ggplot(data, ggplot2::aes_string(x = cfg$x, y = cfg$y)) + ggplot2::geom_col(fill = cfg$color %||% "#0A84FF", alpha = 0.8) + ggplot2::coord_polar() + ggplot2::theme_minimal(base_size = 12) + ggplot2::theme(axis.title = ggplot2::element_blank()) + ggplot2::labs(title = cfg$title %||% NULL); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
